import { useState } from 'react';

const amounts = { USD: [420000, 670000], EUR: [180000, 300000] };
type Currency = keyof typeof amounts;
const approved = 99, awaiting = 6, target = 120;

export default function StatusVocabularyPrimitives() {
  const [pending, setPending] = useState(true);
  const [currency, setCurrency] = useState<Currency>('USD');
  const money = new Intl.NumberFormat('en', { style: 'currency', currency, currencyDisplay: 'code', maximumFractionDigits: 0 });
  const displayed = approved + (pending ? awaiting : 0);
  return <section className="grid min-w-0 gap-4 p-3 text-start text-sm" aria-label="Status and money primitives">
    <div className="flex flex-wrap items-center gap-2" aria-label="Status vocabulary"><span className="inline-flex items-center gap-1.5 rounded-sm border px-2 py-1 font-semibold border-solid bg-emerald-800 text-white"><span aria-hidden="true">→</span>In progress</span>
    <span className="inline-flex items-center gap-1.5 rounded-sm border px-2 py-1 font-semibold border-solid bg-emerald-100 text-emerald-950"><span aria-hidden="true">✓</span>Approved</span>
    <span className="inline-flex items-center gap-1.5 rounded-sm border px-2 py-1 font-semibold border-solid"><span aria-hidden="true">◷</span>Pending review</span>
    <span className="inline-flex items-center gap-1.5 rounded-sm border px-2 py-1 font-semibold border-dashed"><span aria-hidden="true">−</span>On hold</span></div>
    <div><label className="flex items-center gap-2"><input type="checkbox" checked={pending} onChange={e => setPending(e.target.checked)} /> Include pending progress</label>
      <div className="flex h-3 overflow-hidden rounded-sm border" role="progressbar" aria-label="Placement target" aria-valuemin={0} aria-valuemax={target} aria-valuenow={displayed}
        aria-valuetext={approved + ' approved, ' + (pending ? awaiting : 0) + ' pending, target ' + target}>
        <span className="bg-emerald-800" style={{width: approved / target * 100 + '%'}} />
        {pending && <span className="border border-dashed border-emerald-800 bg-emerald-100" style={{width: awaiting / target * 100 + '%'}} />}
      </div>
      <output className="font-mono text-xs">{approved} approved · {pending ? awaiting : 0} pending / {target} target</output>
    </div>
    <div><div className="flex flex-wrap items-center gap-2" role="group" aria-label="Agreement currency">
      {(['USD','EUR'] as const).map(code => <button type="button" key={code} className="rounded-sm border px-2.5 py-1.5 aria-pressed:outline-2" aria-pressed={code === currency} onClick={() => setCurrency(code)}>{code}</button>)}
      </div><dl className="mt-2 flex flex-wrap gap-2" aria-live="polite">
        <div className="inline-flex flex-wrap gap-1 rounded-sm border px-2 py-1 font-mono"><dt>Agreed</dt><dd>{money.format(amounts[currency][0])}</dd></div>
        <div className="inline-flex flex-wrap gap-1 rounded-sm border px-2 py-1 font-mono"><dt>Requested</dt><dd>{money.format(amounts[currency][1])}</dd></div>
      </dl>
    </div>
  </section>;
}
